using namespace std;

int main() {
    string str;
    getline(cin, str);
    int slow = 0;
    int fast = 1;
    int count = 1;
    int ans = 0;
    while (fast < (int)str.length()) {
        char ch = str[slow];
        char ch1 = str[fast];
        if (ch == ch1) {
            count++;
        } else {
            if (count % 2 == 0) {
                ans++;
            }
            slow = fast;
            count = 1;
        }
        fast++;
    }
